window.ScripturaLexicons.BDAG_PART_0142 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-episterizo-bdag\" data-source=\"BDAG\" data-search=\"ἐπιστηρίζω epistērízō verbo fortalecer; firmar; confirmar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπιστηρίζω</td><td>verbo</td><td>fortalecer; firmar; confirmar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epistole-bdag\" data-source=\"BDAG\" data-search=\"ἐπιστολή, ῆς, ἡ epistolḗ substantivo feminino carta; epístola BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπιστολή, ῆς, ἡ</td><td>substantivo feminino</td><td>carta; epístola</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epistomizo-bdag\" data-source=\"BDAG\" data-search=\"ἐπιστομίζω epistomízō verbo calar; silenciar; refrear; impedir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπιστομίζω</td><td>verbo</td><td>calar; silenciar; refrear; impedir</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epistrepho-bdag\" data-source=\"BDAG\" data-search=\"ἐπιστρέφω epistréphō verbo voltar; virar-se; fazer voltar; converter-se BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπιστρέφω</td><td>verbo</td><td>voltar; virar-se; fazer voltar; converter-se</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epistrophe-bdag\" data-source=\"BDAG\" data-search=\"ἐπιστροφή, ῆς, ἡ epistrophḗ substantivo feminino atenção; interesse; conversão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπιστροφή, ῆς, ἡ</td><td>substantivo feminino</td><td>atenção; interesse; conversão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-episunago-bdag\" data-source=\"BDAG\" data-search=\"ἐπισυνάγω episunágō verbo reunir; ajuntar; congregar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπισυνάγω</td><td>verbo</td><td>reunir; ajuntar; congregar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-episunagoge-bdag\" data-source=\"BDAG\" data-search=\"ἐπισυναγωγή, ῆς, ἡ episunagōgḗ substantivo feminino reunião; assembleia; congregação BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπισυναγωγή, ῆς, ἡ</td><td>substantivo feminino</td><td>reunião; assembleia; congregação</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-episuntrecho-bdag\" data-source=\"BDAG\" data-search=\"ἐπισυντρέχω episuntréchō verbo correr juntos; acorrer em grupo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπισυντρέχω</td><td>verbo</td><td>correr juntos; acorrer em grupo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-episurrapto-bdag\" data-source=\"BDAG\" data-search=\"ἐπισυρράπτω episurráptō verbo; variante gráfica e remissão forma de ἐπι(ρ)ράπτω BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπισυρράπτω</td><td>verbo; variante gráfica e remissão</td><td>forma de ἐπι(ρ)ράπτω</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-episustasis-bdag\" data-source=\"BDAG\" data-search=\"ἐπισύστασις, εως, ἡ episústasis substantivo feminino levante; tumulto; perturbação; insurreição BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπισύστασις, εως, ἡ</td><td>substantivo feminino</td><td>levante; tumulto; perturbação; insurreição</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-episphales-bdag\" data-source=\"BDAG\" data-search=\"ἐπισφαλής, ές episphalḗs adjetivo inseguro; perigoso; arriscado BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπισφαλής, ές</td><td>adjetivo</td><td>inseguro; perigoso; arriscado</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-episphragizo-bdag\" data-source=\"BDAG\" data-search=\"ἐπισφραγίζω episphragízō verbo selar; pôr um selo; encerrar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπισφραγίζω</td><td>verbo</td><td>selar; pôr um selo; encerrar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-episkhuo-bdag\" data-source=\"BDAG\" data-search=\"ἐπισχύω episkhúō verbo persistir; insistir; fortalecer-se; resistir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπισχύω</td><td>verbo</td><td>persistir; insistir; fortalecer-se; resistir</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-episoreuo-bdag\" data-source=\"BDAG\" data-search=\"ἐπισωρεύω episōreúō verbo amontoar; acumular; acrescentar em montão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπισωρεύω</td><td>verbo</td><td>amontoar; acumular; acrescentar em montão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epitage-bdag\" data-source=\"BDAG\" data-search=\"ἐπιταγή, ῆς, ἡ epitagḗ substantivo feminino ordem; mandamento; determinação; autoridade BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπιταγή, ῆς, ἡ</td><td>substantivo feminino</td><td>ordem; mandamento; determinação; autoridade</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epitasso-bdag\" data-source=\"BDAG\" data-search=\"ἐπιτάσσω epitássō verbo ordenar; determinar; comandar com autoridade BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπιτάσσω</td><td>verbo</td><td>ordenar; determinar; comandar com autoridade</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epiteleo-bdag\" data-source=\"BDAG\" data-search=\"ἐπιτελέω epiteléō verbo terminar; completar; realizar; levar a cabo; cumprir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπιτελέω</td><td>verbo</td><td>terminar; completar; realizar; levar a cabo; cumprir</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epitedeios-bdag\" data-source=\"BDAG\" data-search=\"ἐπιτήδειος, εία, ον epitḗdeios adjetivo; substantivado apropriado; adequado; necessário; conveniente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπιτήδειος, εία, ον</td><td>adjetivo; substantivado</td><td>apropriado; adequado; necessário; conveniente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epitedeuma-bdag\" data-source=\"BDAG\" data-search=\"ἐπιτήδευμα, ατος, τό epitḗdeuma substantivo neutro ocupação; prática habitual; modo de viver BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπιτήδευμα, ατος, τό</td><td>substantivo neutro</td><td>ocupação; prática habitual; modo de viver</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epitedeuo-bdag\" data-source=\"BDAG\" data-search=\"ἐπιτηδεύω epitēdeúō verbo cultivar; praticar; empenhar-se em BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπιτηδεύω</td><td>verbo</td><td>cultivar; praticar; empenhar-se em</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article id=\"entry-episterizo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιστηρίζω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epistērízō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Futuro <span class=\"greek\">ἐπιστηριῶ</span>, Sl 31:8; primeiro aoristo <span class=\"greek\">ἐπεστήριξα</span>; segunda pessoa singular <span class=\"greek\">ἐπεστήρισας</span>, Sl 37:3. Passivo: futuro <span class=\"greek\">ἐπιστηριχθήσομαι</span>, Jz 16:26; aoristo <span class=\"greek\">ἐπεστηρίχθην</span>, LXX; subjuntivo, terceira pessoa singular <span class=\"greek\">ἐπεστηρισθῇ</span>; perfeito, terceira pessoa singular <span class=\"greek\">ἐπεστήρικται</span>, Jt 8:24, variante de leitura (em lugar de -<span class=\"greek\">ισται</span>); mais-que-perfeito, terceira pessoa singular <span class=\"greek\">ἐπεστήρικτο</span>, LXX (ver <span class=\"greek\">στηρίζω</span>; Aristóteles e outros; LXX).</p>\n<p class=\"entry-text\"><b>Fazer com que alguém se torne mais forte ou mais firme: fortalecer, firmar.</b> Em nossa literatura, acerca dos crentes, de sua dedicação e disposição de permanecer fiéis, sobretudo diante das dificuldades. Com <span class=\"greek\">τινά</span> ou <span class=\"greek\">τί</span>, <i>alguém ou alguma coisa</i>: os irmãos, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.11.2\" target=\"_blank\" rel=\"noopener noreferrer\">At 11:2</a>, códice D; cf. 18:23. As almas (= os corações, como centro da sensibilidade pessoal e da resposta psíquica), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.22\" target=\"_blank\" rel=\"noopener noreferrer\">At 14:22</a>; congregações ou igrejas, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.41\" target=\"_blank\" rel=\"noopener noreferrer\">At 15:41</a>. Em uso absoluto, versículo 32 (subentendido <span class=\"greek\">ἀδελφούς</span>, «irmãos»). — TW.</p></section></article>\n<article id=\"entry-epistole-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιστολή, ῆς, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epistolḗ⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Ver <span class=\"greek\">ἐπιστέλλω</span>.) <b>Carta, epístola</b> (assim Eurípides, Tucídides e posteriores; empréstimo no hebraico rabínico), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.7.8\" target=\"_blank\" rel=\"noopener noreferrer\">2 Co 7:8</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.3.17\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ts 3:17</a>; 1 Cl 47:1; 63:2; IEph 12:2; ISm 11:3; Pol 13:2b.</p>\n<p class=\"entry-text\"><span class=\"greek\">δι</span>’ <span class=\"greek\">ἐπιστολῆς</span>, <i>por meio de carta</i> (Diod. S. 19, 48, 1; Polieno 7, 39; 53ª carta de Apolônio de Tiana [Filóstrato I 358, 9]; Ps.-Demétrio, Form. Ep., p. 5, 10; BGU 884, 6; 1046 II, 5), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ts 2:2</a> (Vi. Aesopi W 104 P.: <span class=\"greek\">ἐ</span>. <span class=\"greek\">ὡς</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Αἰσώπου</span>; Polieno 8, 50: uma carta de duas pessoas falecidas, <span class=\"greek\">ὡς</span> <span class=\"greek\">ἔτι</span> <span class=\"greek\">ζώντων</span>), versículo 15; cf. 3:14.</p>\n<p class=\"entry-text\"><span class=\"greek\">γράφειν</span> <span class=\"greek\">ἐπιστολήν</span>, <i>escrever uma carta</i> (Diod. S. 17, 39, 2; Fílon, Leg. ad Gai. 207), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.23\" target=\"_blank\" rel=\"noopener noreferrer\">At 15:23</a>, códice D; 23:25 (quanto ao gênero específico da comunicação administrativa, ver Taubenschlag, OpMin II, p. 722, com referência a PTebt 45, 27); <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.16.22\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 16:22</a>. <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ἐ</span>., <i>na carta</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.5.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 5:9</a> (isto é, «na carta que conheceis» [ver <span class=\"greek\">ὁ</span> 2a]; como ChronLind B 14: <span class=\"greek\">ἐν</span> <span class=\"greek\">τᾷ</span> <span class=\"greek\">ἐπιστολᾷ</span>; Hipérides 3, 25: <span class=\"greek\">ἐν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἐπιστολαῖς</span>; Platão, Ep. 7, 345c: <span class=\"greek\">ἡ</span> <span class=\"greek\">ἐ</span>. = «a carta conhecida por vós»).</p>\n<p class=\"entry-text\"><span class=\"greek\">ταύτην</span> <span class=\"greek\">δευτέραν</span> <span class=\"greek\">ὑμῖν</span> <span class=\"greek\">γράφω</span> <span class=\"greek\">ἐ</span>., <i>esta é a segunda carta que vos escrevo</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.3.1\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pe 3:1</a> (cf. BGU 827, 20: <span class=\"greek\">ἰδοὺ</span> <span class=\"greek\">τρίτην</span> <span class=\"greek\">ἐπιστολήν</span> <span class=\"greek\">σοι</span> <span class=\"greek\">γράφω</span>; PMich 209, 5: <span class=\"greek\">δευτέραν</span> <span class=\"greek\">ἐπιστολὴν</span> <span class=\"greek\">ἔπεμψά</span> <span class=\"greek\">σοι</span>). <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">Ἰωάννου</span> <span class=\"greek\">προτέρας</span> <span class=\"greek\">ἐ</span>., <i>da primeira carta de João</i>, Pápias 2:17; <span class=\"greek\">αἱ</span> <span class=\"greek\">δύο</span> <span class=\"greek\">ἐπιστολαὶ</span> <span class=\"greek\">αἱ</span> <span class=\"greek\">μικραί</span>, <i>as duas cartas breves</i>, Pápias 11:1.</p>\n<p class=\"entry-text\"><span class=\"greek\">ἀναδιδόναι</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἐπιστολήν</span> <span class=\"greek\">τινι</span>, <i>entregar uma carta a alguém</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.33\" target=\"_blank\" rel=\"noopener noreferrer\">At 23:33</a>; também <span class=\"greek\">ἐπιδιδόναι</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.30\" target=\"_blank\" rel=\"noopener noreferrer\">At 15:30</a>; <span class=\"greek\">διαπέμπεσθαι</span>, <i>enviar</i>, MPol 20:1; <span class=\"greek\">διακονεῖν</span>, <i>cuidar de, ministrar</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">2 Co 3:3</a>; <span class=\"greek\">ἀναγινώσκειν</span>, <i>ler</i> (Xen., An. 1, 6, 4; 1 Mac 10:7; Jos., C. Ap. 2, 37), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Co 3:2</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.4.16\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 4:16</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.27\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ts 5:27</a>.</p>\n<p class=\"entry-text\">Com toda probabilidade, em nossa literatura, o <b>plural</b> — mesmo em <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.2\" target=\"_blank\" rel=\"noopener noreferrer\">At 9:2</a> e Pol 3:2 — designa sempre <b>mais de uma carta</b>, e não uma carta única (como Eur., Iph. A. 111; 314; Tucídides 1, 132, 5; 4, 50, 2; também M. Júlio Bruto, Ep. 1, 1 [de Mitrídates]; 1 Mac 10:3, 7; Jos., Ant. 10, 15; 16). <span class=\"greek\">δι</span>’ <span class=\"greek\">ἐπιστολῶν</span>, <i>por cartas</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.16.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 16:3</a>. <span class=\"greek\">τῷ</span> <span class=\"greek\">λόγῳ</span> <span class=\"greek\">δι</span>’ <span class=\"greek\">ἐπιστολῶν</span> <span class=\"greek\">ἀπόντες</span>, <i>(fazer algo) mediante palavras em cartas, quando estamos ausentes</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.10.11\" target=\"_blank\" rel=\"noopener noreferrer\">2 Co 10:11</a> (cf. UPZ 69, 3 [152 a.C.]: <span class=\"greek\">ἀπόντος</span> <span class=\"greek\">μου</span> … <span class=\"greek\">διὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἐπιστολίου</span>); versículo 9; <span class=\"greek\">ἐ</span>. <span class=\"greek\">βαρεῖαι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἰσχυραί</span>, <i>as cartas são graves e vigorosas</i>, versículo 10. <span class=\"greek\">ἔγραψεν</span> <span class=\"greek\">ὑμῖν</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">πάσαις</span> <span class=\"greek\">ἐ</span>., <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pe 3:16</a>. <span class=\"greek\">ἐ</span>. <span class=\"greek\">συστατικαί</span>, <i>cartas de recomendação</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.3.1\" target=\"_blank\" rel=\"noopener noreferrer\">2 Co 3:1</a> (ver <span class=\"greek\">συστατικός</span>).</p>\n<p class=\"entry-text\"><span class=\"greek\">ἐπιστολὰς</span> <span class=\"greek\">πέμπειν</span>, <i>enviar cartas</i> (Ps.-Demóstenes 11, 17; Diod. S. 17, 23, 6: <span class=\"greek\">ἔπεμψεν</span> <span class=\"greek\">ἐπιστολάς</span> = «cartas»; OGI 42, 6; 2 Mac 11:34), IPol 8:1; cf. Pol 13:2a. <span class=\"greek\">ἐπιστολὴ</span> <span class=\"greek\">πρός</span> <span class=\"greek\">τινα</span>, <i>carta dirigida a alguém</i> (2 Esdr 12:7; 2 Mac 11:27; Jos., C. Ap. 1, 111), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.2\" target=\"_blank\" rel=\"noopener noreferrer\">At 9:2</a>; 22:5 (cartas que autorizavam prender pessoas e entregá-las às autoridades na capital, como PTebt 315, 29ss. [século II d.C.]); <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.3.1\" target=\"_blank\" rel=\"noopener noreferrer\">2 Co 3:1</a> (<span class=\"greek\">πρὸς</span> <span class=\"greek\">ὑμᾶς</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">ἐξ</span> <span class=\"greek\">ὑμῶν</span>).</p>\n<p class=\"entry-text\">Também as subscrições epistolares tardias das cartas do NT, bem como B, 1 Cl e 2 Cl. — G. Bahr, «Paul and Letter Writing in the First Century», CBQ 28 (1966), pp. 465–477; J. White, <i>Light from Ancient Letters</i> (1986), pp. 3–20, 221–224 e bibliografia; bibliografia sob <span class=\"greek\">χαίρω</span> 2b; B. 1286; RAC II, pp. 564–585. — DELG, s.v. <span class=\"greek\">στέλλω</span>; M-M; EDNT; TW.</p></section></article>\n<article id=\"entry-epistomizo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιστομίζω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epistomízō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Literalmente, «colocar alguma coisa sobre a boca»; em sentido figurado (ver <span class=\"greek\">στόμα</span>; Aristófanes, Eq. 845; Platão, Gorg. 482e e outros; Plut., Mor. 156a; 810e): <b>silenciar alguém, fazer calar.</b> Com <span class=\"greek\">τινά</span>, <i>alguém</i> (Demóstenes 7, 33; Libânio, Or. 2, p. 243, 20 F.): <span class=\"greek\">οὓς</span> <span class=\"greek\">δεῖ</span> <span class=\"greek\">ἐπιστομίζειν</span>, <i>aqueles que devem ser silenciados</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">Tt 1:11</a>.</p>\n<p class=\"entry-text\">Também é provável o sentido <b>refrear, obstruir, impedir</b> (Luciano, Pro Im. 10; Calumn. 12; Fílon, Det. Pot. Insid. 23; Jos., Ant. 17, 251), especialmente no mesmo versículo, em uma variante de leitura que é adição do minúsculo 460: <span class=\"greek\">τὰ</span> <span class=\"greek\">τέκνα</span> … <span class=\"greek\">ἐπιστόμιζε</span>, <i>silencia os filhos</i>. — DELG, s.v. <span class=\"greek\">στόμα</span>; M-M; Spicq.</p></section></article>\n<article id=\"entry-epistrepho-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιστρέφω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epistréphō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Futuro <span class=\"greek\">ἐπιστρέψω</span>; primeiro aoristo <span class=\"greek\">ἐπέστρεψα</span>. Passivo: futuro <span class=\"greek\">ἐπιστραφήσομαι</span>; segundo aoristo passivo <span class=\"greek\">ἐπεστράφην</span> (ver o verbete seguinte e <span class=\"greek\">στρέφω</span>; Homero e posteriores). Em geral, «voltar-se para».</p>\n<p class=\"entry-text\"><b>① Retornar ao ponto em que se esteve: virar-se, voltar, regressar.</b></p>\n<p class=\"entry-text\"><b>ⓐ Ativo intransitivo</b> (Xen., Hell. 4, 5, 16; Políbio 1, 47, 8; Eliano, VH 1, 6; LXX; En 99:5s.; ParJer 7:31). Em uso absoluto, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.55\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 8:55</a> (cf. Jz 15:19); <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.36\" target=\"_blank\" rel=\"noopener noreferrer\">At 15:36</a>; 16:18; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 1:12</a>b. Com <span class=\"greek\">εἴς</span> <span class=\"greek\">τι</span>, <i>para algum lugar</i> (SIG 709, 11 [cerca de 107 a.C.]; 2 Km 15:27; 1 Esdr 5:8; 1 Mac 5:68; 3 Mac 7:8: <span class=\"greek\">εἰς</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἴδια</span> <span class=\"greek\">ἐ</span>.), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.44\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:44</a> (exorcismo de espíritos malignos para que nunca retornem; cf. Jos., Ant. 8, 45; 47: <span class=\"greek\">μηκέτ</span>’ <span class=\"greek\">εἰς</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">ἐπανήξειν</span>); <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.39\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 2:39</a>. <span class=\"greek\">εἰς</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ὀπίσω</span>, <i>para trás</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 13:16</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.31\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 17:31</a>; também <span class=\"greek\">ἐ</span>. <span class=\"greek\">ὀπίσω</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:18</a>. Com <span class=\"greek\">ἐπί</span> <span class=\"greek\">τι</span> (SIG 709, 20), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.22\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pe 2:22</a>; <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινα</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.6\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 10:6</a>, códice D; <span class=\"greek\">πρός</span> <span class=\"greek\">τινα</span>, <i>a alguém</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 17:4</a>. Seguido de infinitivo com valor final (Jt 8:11, variante; ApcMos 31: <span class=\"greek\">ἐπιστρέψῃ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἐλεῆσαι</span> <span class=\"greek\">ἡμᾶ</span>): <span class=\"greek\">βλέπειν</span>, <i>para ver</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 1:12</a>a (ver <span class=\"greek\">φωνή</span> 2e). Também simplesmente <i>virar-se</i>: <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">σῶμα</span>, <i>em direção ao corpo</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.40\" target=\"_blank\" rel=\"noopener noreferrer\">At 9:40</a> (para <span class=\"greek\">ἐ</span>. <span class=\"greek\">πρός</span> com acusativo, cf. Esopo, Fab. 141 P. = 248 H., Ch. 202, H.H. 146 I e III [<span class=\"greek\">ἐστράφη</span> em II]; 1 Mac 7:25; 11:73).</p>\n<p class=\"entry-text\"><b>ⓑ Aoristo passivo empregado com sentido ativo</b> (Eur., Alc. 188; 1 Mac 4:24): <span class=\"greek\">εἰς</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ὀπίσω</span>, <i>para trás</i> (Luciano, Catapl. 14), Hv 4, 3, 7. A respeito de uma saudação que volta sem ter sido utilizada, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:13</a>.</p>\n<p class=\"entry-text\"><b>② Mudar de direção, virar-se.</b> Aoristo passivo com sentido ativo (Heródoto 3, 156; Xen., Cyr. 6, 4, 10; Symp. 9, 1 e outros; Jos., Ant. 7, 265; 16, 351): <span class=\"greek\">ἐπιστραφεὶς</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ὄχλῳ</span>, <i>virou-se no meio da multidão</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 5:30</a>; <span class=\"greek\">ἐπιστραφεὶς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἰδών</span>, <i>virando-se e vendo</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 8:33</a> (Jos., Bell. 2, 619: <span class=\"greek\">ἐπιστραφεὶς</span> <span class=\"greek\">κ</span>. <span class=\"greek\">θεασάμενος</span>). <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.21.20\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 21:20</a> (única ocorrência em João; ver M.-É. Boismard, «Le chapitre 21 de St. Jean», RB 54 [1947], p. 488). MPol 12:3. <span class=\"greek\">μὴ</span> <span class=\"greek\">ἐπιστραφείς</span>, <i>sem se virar</i> = <i>sem se incomodar com isso</i>, MPol 8:3.</p>\n<p class=\"entry-text\"><b>③ Fazer uma pessoa mudar de crença ou de conduta, com ênfase naquilo para o qual se volta: fazer voltar, converter.</b> Ativo transitivo, em sentido espiritual ou moral (Plut., Mor. 21c: <span class=\"greek\">ἐ</span>. <span class=\"greek\">τινὰ</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">καλόν</span>; Jos., Ant. 10, 53). Com <span class=\"greek\">τινά</span> ou <span class=\"greek\">τὶ</span> <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινα</span>, <i>alguém ou alguma coisa para alguém</i> (2 Cr 19:4; Jt 7:30; PsSol 8:27): <span class=\"greek\">πολλοὺς</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">κύριον</span>, <i>muitos ao Senhor</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 1:16</a>; <span class=\"greek\">καρδίας</span> <span class=\"greek\">πατέρων</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τέκνα</span>, <i>corações dos pais para os filhos</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 1:17</a> (cf. Sir 48:10; Hesíodo, Op. 182). Com <span class=\"greek\">τινὰ</span> <span class=\"greek\">ἔκ</span> <span class=\"greek\">τινος</span>, <i>fazer alguém voltar de alguma coisa</i> (cf. Ml 2:6), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.20\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 5:20</a>; cf. versículo 19.</p>\n<p class=\"entry-text\">Quanto à ação divina: <span class=\"greek\">τοὺς</span> <span class=\"greek\">πλανωμένους</span> <span class=\"greek\">ἐπίστρεψον</span>, <i>faze voltar aqueles que se desviaram</i>, 1 Cl 59:4; cf. Hm 8:10. Semelhantemente, acerca de presbíteros, Pol 6:1; cf. 2 Cl 17:2. <span class=\"greek\">ὅταν</span> <span class=\"greek\">τις</span> <span class=\"greek\">ἡμᾶς</span> … <span class=\"greek\">ἐπιστρέψῃ</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀδικίας</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">δικαιοσύνην</span>, <i>quando alguém nos faz voltar da injustiça para a justiça</i>, 2 Cl 19:2. <span class=\"greek\">τὸν</span> <span class=\"greek\">οἶκον</span> … <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">κύριον</span>, <i>a casa … para o Senhor</i>, Hv 1, 3, 1; cf. Ox 850, 7.</p>\n<p class=\"entry-text\"><b>④ Mudar de pensamento ou de conduta, para melhor ou pior: voltar-se, retornar.</b></p>\n<p class=\"entry-text\"><b>ⓐ Ativo intransitivo</b> (Sl 77:41; 2 Esdr 19:28; ApcSed 12:4s.): <i>voltar, regressar</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.16\" target=\"_blank\" rel=\"noopener noreferrer\">At 15:16</a>, códice D. <i>Arrepender-se</i>, Hs 9, 26, 2. Com <span class=\"greek\">ἐπί</span> <span class=\"greek\">τι</span>, <i>para algo</i>, 1 Cl 9:1; Pol 7:2; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.9\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 4:9</a>. Com <span class=\"greek\">ἔκ</span> <span class=\"greek\">τινος</span>, <i>de alguma coisa</i> (cf. 3 Km 13:26), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.21\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pe 2:21</a>, variante.</p>\n<p class=\"entry-text\">Especialmente de uma mudança na relação do pecador com Deus: <b>voltar-se (para Deus)</b>, frequentemente na LXX. Com <span class=\"greek\">ἐπί</span> e acusativo (<span class=\"greek\">ἐπὶ</span> <span class=\"greek\">κύριον</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">θεόν</span>, Teófilo de Antioquia 3, 11 [p. 226, 25]): <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">κύριον</span>, <i>ao Senhor</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.35\" target=\"_blank\" rel=\"noopener noreferrer\">At 9:35</a>; 11:21; Hs 9, 26, 3; <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">θεόν</span>, <i>a Deus</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.20\" target=\"_blank\" rel=\"noopener noreferrer\">At 26:20</a>; cf. 1 Cl 18:13; 2 Cl 16:1. <span class=\"greek\">πρὸς</span> (<span class=\"greek\">τὸν</span>) <span class=\"greek\">κύριον</span> (1 Km 7:3; Os 5:4; 6:1; Am 4:6 e outros na LXX), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">2 Co 3:16</a>; Hm 6, 1, 5; Hm 12, 6, 2. <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">θεόν</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ts 1:9</a> (terminologia não paulina para conversão, segundo G. Friedrich, TZ 51 [1965], p. 504).</p>\n<p class=\"entry-text\">Nesta última passagem, e por vezes em outras, acrescenta-se aquilo <b>de que alguém se volta</b>, com <span class=\"greek\">ἀπό</span> e genitivo (2 Cr 6:26; Br 2:33, variante; <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">πασῶν</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἁμαρτιῶν</span>, Teófilo de Antioquia 3, 11 [p. 228, 10]), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.15\" target=\"_blank\" rel=\"noopener noreferrer\">At 14:15</a>; talvez 15:19. <span class=\"greek\">ἐ</span>. <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">σκότους</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">φῶς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἐξουσίας</span> <span class=\"greek\">τ</span>. <span class=\"greek\">σατανᾶ</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θεόν</span>, <i>voltar-se das trevas para a luz e do poder de Satanás para Deus</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.18\" target=\"_blank\" rel=\"noopener noreferrer\">At 26:18</a>. Em uso absoluto, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:15</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 4:12</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.27\" target=\"_blank\" rel=\"noopener noreferrer\">At 28:27</a> (todos citam Is 6:10); <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.32\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 22:32</a> (ver C. Pickar, CBQ 4 [1942], pp. 137–140); com <span class=\"greek\">μετανοεῖν</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.19\" target=\"_blank\" rel=\"noopener noreferrer\">At 3:19</a>.</p>\n<p class=\"entry-text\"><b>ⓑ Aoristo passivo com sentido ativo: voltar-se para.</b> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">εἴδωλα</span>, <i>às imagens (de divindades)</i>, B 4:8; <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">διχοστασίαν</span>, <i>à desunião</i>, Hs 8, 7, 5. Em sentido favorável, <i>voltar-se</i> (Ps.-Demóstenes 10, 9; Epicteto 2, 20, 22: <span class=\"greek\">οἱ</span> <span class=\"greek\">πολῖται</span> <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">ἐπιστραφέντες</span> <span class=\"greek\">τιμῶσι</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">θεῖον</span>; Dt 30:10; Jr 3:14; Sl 7:13 e outros; ApcSed 14:6: <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ἐμὸν</span> <span class=\"greek\">βάπτισμα</span>). Com <span class=\"greek\">ἐ</span>. <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινα</span> (Is 55:7), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.25\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pe 2:25</a>; <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">δεσπότην</span>, <i>ao Soberano</i>, 1 Cl 7:5. Com <span class=\"greek\">πρός</span> <span class=\"greek\">τινα</span> (Diógenes Laércio 3, 25, todos os gregos para Platão; Sinésio, Provid. 1, 9, 97c: <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">θεόν</span>), <span class=\"greek\">πρὸς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">κύριον</span> (Os 14:2s.; Jl 2:13 e outros), Hm 12, 6, 2; <span class=\"greek\">πρός</span> <span class=\"greek\">με</span> (Am 4:8; Jl 2:12 e outros), 1 Cl 8:3 (citação escriturística de origem desconhecida). Em uso absoluto, <i>ser convertido</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.40\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 12:40</a>, variante; Hm 12, 4, 6; <span class=\"greek\">ἐγγὺς</span> <span class=\"greek\">κύριος</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἐπιστρεφομένοις</span>, <i>o Senhor está perto daqueles que a ele se voltam</i>, Hv 2, 3, 4. — A. Nock, <i>Conversion</i> (1933); E. Dietrich, <i>Die Umkehr (Bekehrung u. Busse im AT u. Judentum)</i> (1936). — M-M; TW; Sv.</p></section></article>\n<article id=\"entry-epistrophe-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιστροφή, ῆς, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epistrophḗ⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Ver o verbete precedente; poetas trágicos, Tucídides e posteriores; inscrições, papiros, LXX, Josefo; Just., D. 30, 1; com vários sentidos.) Em nossa literatura, somente com valor intransitivo: «voltar-se (para)».</p>\n<p class=\"entry-text\"><b>① Ato de voltar a atenção para algo: atenção, interesse.</b> (Sófocles e outros; <span class=\"greek\">ἡ</span> <span class=\"greek\">πρός</span> <span class=\"greek\">ἀνθρώπους</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>, <i>a atenção de Deus para com os seres humanos</i>, Orígenes, C. Cels. 4, 5, 26.) <span class=\"greek\">ἐ</span>. <span class=\"greek\">ποιεῖσθαι</span>, <i>dar atenção, ocupar-se de</i> (Demóstenes 12, 1; 19, 306; Apiano, Bell. Civ. 4, 35 §148; Michel 543, 3; PPetr II, 19 [2], 2; Jos., Ant. 9, 237), com <span class=\"greek\">περί</span> <span class=\"greek\">τινος</span> (Crisipo, Stoic. III 187; SIG 685, 128 [139 a.C.]), 1 Cl 1:1.</p>\n<p class=\"entry-text\"><b>② Mudança de maneira de pensar ou de crença: conversão.</b> (Sir 18:21; 49:2; PsSol 16:11; Jos., Ant. 2, 293; Just., D. 30, 1; Orígenes, C. Cels. 1, 43, 39; Porfírio, <i>Ad Marcellam</i> 24: <span class=\"greek\">μόνη</span> <span class=\"greek\">σωτηρία</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θεὸν</span> <span class=\"greek\">ἐπιστροφή</span>, <i>a única salvação é a conversão para Deus</i>; Hiérocles 24, p. 473; Simplício, p. 107, 22: <span class=\"greek\">ἡ</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">θεῖον</span> <span class=\"greek\">ἐπιστροφή</span>.) <span class=\"greek\">τῶν</span> <span class=\"greek\">ἐθνῶν</span>, <i>dos gentios</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.3\" target=\"_blank\" rel=\"noopener noreferrer\">At 15:3</a>; <span class=\"greek\">εἶναι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">τινι</span>, <i>ser um meio de conversão para alguém</i>, B 11:8. — P. Aubin, <i>Le problème de la ‘conversion’</i> (1963); DELG, s.v. <span class=\"greek\">στρέφω</span>; M-M; TW.</p></section></article>\n<article id=\"entry-episunago-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπισυνάγω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦episunágō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Futuro <span class=\"greek\">ἐπισυνάξω</span>; infinitivo do primeiro aoristo <span class=\"greek\">ἐπισυνάξαι</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.24\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 13:24</a>, assim como infinitivo do segundo aoristo <span class=\"greek\">ἐπισυναγαγεῖν</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.37\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:37</a> (W-S. §13, 10; Mlt-H. 226). Passivo: primeiro futuro <span class=\"greek\">ἐπισυναχθήσομαι</span>; primeiro aoristo <span class=\"greek\">ἐπισυνήχθην</span>; perfeito, terceira pessoa singular <span class=\"greek\">ἐπισυνῆκται</span>, 1 Mac 15:12; particípio <span class=\"greek\">ἐπισυνηγμένος</span> (ver o verbete seguinte; Políbio; Plut., Mor. 894a e outros; inscrições, papiros, LXX, En; TestSol D 3, 3s.; Test12Patr; GrBar 15:2; ApcMos 29; EpArist; Josefo).</p>\n<p class=\"entry-text\">Em nossa literatura, sempre equivalente a <span class=\"greek\">συνάγω</span> (cf. <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.37\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 17:37</a> = <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:28</a>): <b>juntar, reunir, congregar</b>, com <span class=\"greek\">τινά</span>, <i>alguém</i> (3 Km 18:20 [<span class=\"greek\">συναγ</span>., variante de leitura]; Sl 105:47 e outros; TestNapht 8:3): <span class=\"greek\">τὰ</span> <span class=\"greek\">τέκνα</span>, <i>os filhos</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.37\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:37</a>a; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.34\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 13:34</a>. Acerca de uma galinha que reúne sua ninhada, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.37\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:37</a>b. <span class=\"greek\">τοὺς</span> <span class=\"greek\">ἐκλεκτοὺς</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">τεσσάρων</span> <span class=\"greek\">ἀνέμων</span>, <i>os escolhidos, dos quatro ventos</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.31\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:31</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 13:27</a>.</p>\n<p class=\"entry-text\">Voz passiva: <b>ser reunido</b> (OGI 90, 23; SIG 700, 21 [117 a.C.]; 2 Cr 20:26; 1 Esdr 9:5 e outros; En 22:3; Fílon, Op. M. 38): acerca de aves de rapina ao redor de um cadáver, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.37\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 17:37</a>; de uma multidão que se reúne (Jos., Ant. 18, 37), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.1\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 12:1</a>; <span class=\"greek\">ὅλη</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">πόλις</span>, <i>toda a cidade</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 1:33</a>. — DELG, s.v. <span class=\"greek\">ἄγω</span>; M-M.</p></section></article>\n<article id=\"entry-episunagoge-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπισυναγωγή, ῆς, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦episunagōgḗ⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Ver o verbete precedente; dificilmente se distingue de <span class=\"greek\">συναγωγή</span>: IG XII/3, suplemento n.º 1270, 11s. [século II a.C.]; ver Deissmann, LO 81; LAE 101ss.; 2 Mac 2:7.)</p>\n<p class=\"entry-text\"><b>① Ato de reunir pessoas em direção a determinado lugar: encontro, reunião.</b> Acerca de um grupo cristão: <span class=\"greek\">ἐγκαταλείπειν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">ἑαυτῶν</span>, <i>negligenciar as próprias reuniões</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.25\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:25</a>.</p>\n<p class=\"entry-text\"><b>② Ação de <span class=\"greek\">ἐπισυνάγεσθαι</span>: reunião, congregação.</b> Com <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινα</span>, <i>com alguém</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ts 2:1</a>. — M-M; TW; Spicq.</p></section></article>\n<article id=\"entry-episuntrecho-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπισυντρέχω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦episuntréchō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Hápax legómenon (cf. <span class=\"greek\">συντρέχω</span>, «correr juntos»). <b>Acorrer em conjunto</b>, acerca de multidões, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 9:25</a>.</p></section></article>\n<article id=\"entry-episurrapto-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπισυρράπτω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦episurráptō⟧</span><span class=\"separator\">·</span><span>verbo; variante gráfica e remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Forma equivalente a <span class=\"greek\">ἐπι</span>(<span class=\"greek\">ρ</span>)<span class=\"greek\">ράπτω</span> (ver esse verbete), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 2:21</a>, códice D.</p></section></article>\n<article id=\"entry-episustasis-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπισύστασις, εως, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦episústasis⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><b>Reunião de pessoas contra a autoridade estabelecida: levante, perturbação, tumulto, insurreição.</b> (De <span class=\"greek\">σύστασις</span>, «reunião»; Sexto Empírico, Eth. 127; Beroso, 680, fragmento 9 [em Jos., C. Ap. 1, 149]; SIG 708, 27 [século I a.C.]; PEnteux 86, 5 [221 a.C.]; Nm 17:5; 26:9; 1 Esdr 5:70; Artápano, 726, fragmento 2 [em Eus., PE 9, 23, 1] Jac.) <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.12\" target=\"_blank\" rel=\"noopener noreferrer\">At 24:12</a>, variante de leitura (em lugar de <span class=\"greek\">ἐπίστασις</span>). Sobre <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.28\" target=\"_blank\" rel=\"noopener noreferrer\">2 Co 11:28</a>, variante de leitura, ver <span class=\"greek\">ἐπίστασις</span>. — DELG, s.v. <span class=\"greek\">ἵστημι</span>; M-M.</p></section></article>\n<article id=\"entry-episphales-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπισφαλής, ές</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦episphalḗs⟧</span><span class=\"separator\">·</span><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Hipócrates, Platão e outros; Diod. S. 13, 77, 2; POxy 75, 20; Sb 9:14; Fílon, Praem. 33; Jos., Ant. 5, 52; 139.) <b>Que pode ocasionar um acidente ou infortúnio: inseguro, perigoso, arriscado.</b> Acerca de uma viagem marítima no outono, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.9\" target=\"_blank\" rel=\"noopener noreferrer\">At 27:9</a>. — DELG, s.v. <span class=\"greek\">σφάλλω</span>; M-M.</p></section></article>\n<article id=\"entry-episphragizo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπισφραγίζω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦episphragízō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Ver <span class=\"greek\">σφραγίζω</span>.) Primeiro aoristo <span class=\"greek\">ἐπεσφράγισα</span> (Diod. S. 14, 55, 1: <span class=\"greek\">βιβλίον</span> <span class=\"greek\">ἐπεσφραγισμένον</span>; papiros; 2 Esdr 20:1; TestSol 7:8: <span class=\"greek\">ἐπεσφράγισα</span>; a voz média ocorre em Platão e outros; Fílon e Melitão, P. 57, 415). <b>Colocar um selo sobre alguma coisa: selar.</b> <span class=\"greek\">τ</span>. <span class=\"greek\">διωγμόν</span>, <i>a perseguição</i>, pondo-lhe assim fim, como a uma carta, MPol 1:1. — DELG, s.v. <span class=\"greek\">σφραγίς</span>.</p></section></article>\n<article id=\"entry-episkhuo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπισχύω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦episkhúō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Imperfeito <span class=\"greek\">ἐπίσχυον</span>; aoristo, terceira pessoa plural, <span class=\"greek\">ἐπίσχυσαν</span>, 1 Mac 6:6 (ver <span class=\"greek\">ἰσχύς</span>; Xenofonte e outros; BGU 1761, 3 [século I a.C.]). Do transitivo «tornar forte» chega-se facilmente ao intransitivo <b>tornar-se mais forte</b>, no sentido de possuir recursos adicionais ou ser persistente em fazer alguma coisa (Teofrasto e outros; Vett. Val. 48, 6: <span class=\"greek\">τῶν</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">τοιούτων</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">λόγος</span> <span class=\"greek\">ἐπισχύσει</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">συμβουλίαν</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">διδαχήν</span>; 1 Mac 6:6).</p>\n<p class=\"entry-text\"><b>Persistir, insistir.</b> <span class=\"greek\">ἐπίσχυον</span> <span class=\"greek\">λέγοντες</span>, <i>insistiam dizendo</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.5\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 23:5</a> (M. Black, <i>An Aramaic Approach</i>³ [1967], p. 255 [siríaco antigo]). <span class=\"greek\">ἀπέρχομαι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">κάμινον</span> <span class=\"greek\">πυρὸς</span> … <span class=\"greek\">καὶ</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἐπισ̣χ̣ύ̣ω</span>, <span class=\"greek\">ἐὰν</span> <span class=\"greek\">μὴ</span>, <i>entro numa fornalha de fogo … mas não consigo resistir, a menos que</i>, AcPl Ha 6, 19–21. — DELG, s.v. <span class=\"greek\">ἰσχύ</span>; M-M.</p></section></article>\n<article id=\"entry-episoreuo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπισωρεύω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦episōreúō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(De <span class=\"greek\">σωρεύω</span>, «amontoar uma coisa sobre outra»; Epicteto 1, 10, 5; Vett. Val. 332, 24; 344, 13 e outros; Jó 14:17, Símaco; SSol 2:4.) <b>Acrescentar em pilha ou montão</b>; figuradamente, <b>amontoar, acumular</b>: <span class=\"greek\">διδασκάλους</span>, <i>acumular um grande número de mestres</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.3\" target=\"_blank\" rel=\"noopener noreferrer\">2 Tm 4:3</a>. Com <span class=\"greek\">τινί</span>, <i>além de</i> (Ateneu 3, 123e): <span class=\"greek\">ἐ</span>. <span class=\"greek\">ταῖς</span> <span class=\"greek\">ἁμαρτίαις</span> <span class=\"greek\">ὑμῶν</span>, <i>acumular pecado sobre pecado</i>, B 4:6. — DELG, s.v. <span class=\"greek\">σωρό</span>; M-M; TW.</p></section></article>\n<article id=\"entry-epitage-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιταγή, ῆς, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epitagḗ⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Ver <span class=\"greek\">τάσσω</span> e o verbete seguinte; Políbio e outros; Diod. S. 1, 70, 1: <span class=\"greek\">νόμων</span> <span class=\"greek\">ἐπιταγή</span>; inscrições; PFlor 119, 5; LXX, En; PsSol 18:12; EpArist.)</p>\n<p class=\"entry-text\"><b>① Diretriz dotada de autoridade: ordem, mandamento, determinação, injunção.</b> <span class=\"greek\">ἐπιταγὴν</span> <span class=\"greek\">ἔχειν</span>, <i>ter uma ordem</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.25\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 7:25</a>. <span class=\"greek\">κατ</span>’ <span class=\"greek\">ἐπιταγήν</span>, <i>de acordo com a ordem</i> = <i>por ordem</i> (SIG 1153; 1171, 3; IG XII/1, 785; JHS 26 [1906], p. 28, n.º 6: <span class=\"greek\">κατ</span>’ <span class=\"greek\">ἐ</span>. <span class=\"greek\">τ</span>. <span class=\"greek\">θεοῦ</span>; PGM 12, 62; 1 Esdr 1:16; En 5:2), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.16.26\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 16:26</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Tm 1:1</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">Tt 1:3</a>; Hv 3, 8, 2. Mas <span class=\"greek\">κατ</span>’ <span class=\"greek\">ἐ</span>. também apresenta outro sentido: <span class=\"greek\">κατ</span>’ <span class=\"greek\">ἐ</span>. <span class=\"greek\">λέγειν</span>, <i>falar como ordem ou mandamento</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 7:6</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.8.8\" target=\"_blank\" rel=\"noopener noreferrer\">2 Co 8:8</a>.</p>\n<p class=\"entry-text\"><b>② Direito ou poder de dar ordens: autoridade.</b> <span class=\"greek\">μετὰ</span> <span class=\"greek\">πάσης</span> <span class=\"greek\">ἐ</span>., <i>com toda autoridade, com plena autoridade</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">Tt 2:15</a>. — DELG, s.v. <span class=\"greek\">τάσσω</span>; <i>New Docs</i> 2, p. 86; M-M; TW.</p></section></article>\n<article id=\"entry-epitasso-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιτάσσω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epitássō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Primeiro aoristo <span class=\"greek\">ἐπέταξα</span>. Passivo: segundo aoristo <span class=\"greek\">ἐπετάγην</span>, LXX; perfeito, terceira pessoa singular, <span class=\"greek\">ἐπιτέτακται</span>, 1 Esdr 5:50; Ar. 4, 2; particípio <span class=\"greek\">ἐπιτεταγμένος</span> (ver o verbete precedente; poetas trágicos, Heródoto e posteriores; inscrições, papiros, LXX, pseudoepígrafos, Josefo; Ar. 4, 2; Tat. 16, 1). <b>Ordenar com autoridade: mandar, determinar.</b></p>\n<p class=\"entry-text\">Com dativo <span class=\"greek\">τινί</span>, <i>a alguém</i> (Sófocles, Ant. 664; Xen., Cyr. 4, 2, 33; SIG 83, 33; PTebt 59, 9; Gn 49:33; Est 1:1q, 8), B 19:7; D 4:10. <span class=\"greek\">τοῖς</span> <span class=\"greek\">πνεύμασι</span>, <i>aos espíritos</i> (cf. PGM 12, 316a: <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span>), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 1:27</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.36\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 4:36</a>; cf. <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 9:25</a>; ao vento e às ondas (cf. 2 Mac 9:8), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 8:25</a>.</p>\n<p class=\"entry-text\">Com <span class=\"greek\">τί</span> <span class=\"greek\">τινι</span>, <i>algo a alguém</i> (Heródoto; SIG 748, 25 [71 a.C.]; Jos., Ant. 1, 172): <span class=\"greek\">τινὶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἀνῆκον</span>, <i>ordenar a alguém que cumpra o seu dever</i>, Fm 8. Com dativo e infinitivo (Heródoto e outros): presente (Xen., An. 2, 3, 6; 1 Mac 4:41), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.2\" target=\"_blank\" rel=\"noopener noreferrer\">At 23:2</a>; Hs 9, 4, 4; 9, 5, 1; com infinitivo aoristo (Xen., Cyr. 7, 3, 14; SIG 683, 37 [140 a.C.]; OGI 443, 2), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.39\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 6:39</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.31\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 8:31</a>.</p>\n<p class=\"entry-text\"><span class=\"greek\">ἐ</span>. seguido de infinitivo aoristo sem dativo (grego anterior; também frequente na LXX): <span class=\"greek\">ἐπέταξεν</span> <span class=\"greek\">ἐνέγκαι</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">κεφαλὴν</span> <span class=\"greek\">αὐτοῦ</span>, <i>ordenou que lhe trouxessem a cabeça</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 6:27</a>. Em uso absoluto (Tucídides 1, 140, 2; POxy 294, 21 [22 d.C.]: <span class=\"greek\">ὡς</span> <span class=\"greek\">ἐπέταξεν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ἡγεμών</span>; Est 8:8; 1 Mac 10:81; PGM 12, 316b), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.14.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 14:22</a>; B 6:18.</p>\n<p class=\"entry-text\">Passivo: <span class=\"greek\">ἐξελίσσειν</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">ἐπιτεταγμένους</span> <span class=\"greek\">αὐτοῖς</span> <span class=\"greek\">ὁρισμούς</span>, <i>percorrer suas órbitas prescritas</i>, 1 Cl 20:3. <span class=\"greek\">τὰ</span> <span class=\"greek\">ἐπιτασσόμενα</span> (SIG 742, 2; POxy 275, 11) <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">βασιλέως</span>, <i>as ordens do rei</i>, 1 Cl 37:3 (cf. SIG 748, 18: <span class=\"greek\">τὰ</span> <span class=\"greek\">ἐπιτασσόμενα</span> <span class=\"greek\">ὑπ</span>’ <span class=\"greek\">αὐτῶν</span>; Herm. Wr. 16, 10b: <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θεῶν</span>). — M-M; TW.</p></section></article>\n<article id=\"entry-epiteleo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιτελέω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epiteléō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Futuro <span class=\"greek\">ἐπιτελέσω</span>; primeiro aoristo <span class=\"greek\">ἐπετέλεσα</span>. Passivo: primeiro futuro <span class=\"greek\">ἐπιτελεσθήσομαι</span>, LXX; aoristo <span class=\"greek\">ἐπετελέσθην</span> (Heródoto e posteriores; frequente em decretos cívicos).</p>\n<p class=\"entry-text\"><b>① Terminar alguma coisa iniciada: concluir, pôr fim, acabar, completar.</b> (1 Km 3:12; 1 Esdr 4:55; 6:27.) Com <span class=\"greek\">τὶ</span>, <i>alguma coisa</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.28\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 15:28</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 1:6</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.8.6\" target=\"_blank\" rel=\"noopener noreferrer\">2 Co 8:6</a>, 11a. Em uso absoluto, versículo 11b. Também <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 3:3</a>, seja como voz média: <i>começastes no Espírito; acabareis agora na carne?</i>; seja, menos provavelmente, como passiva: <i>sereis aperfeiçoados na carne?</i>, com referência aos judaizantes.</p>\n<p class=\"entry-text\"><b>② Produzir um resultado conforme um plano ou objetivo: completar, realizar, executar, efetuar, levar a cabo.</b> (IMagnMai 17, 25.) Com <span class=\"greek\">τὶ</span>, <i>alguma coisa</i>: <span class=\"greek\">πάντα</span>, <i>tudo</i> (1 Esdr 8:16), 1 Cl 1:3; 2:8; 48:4. <span class=\"greek\">πᾶν</span> <span class=\"greek\">ἔργον</span> <span class=\"greek\">ἀγαθόν</span>, <i>toda boa obra</i>, 1 Cl 33:1 (POslo 137, 9 [século III d.C.]: <span class=\"greek\">ἐ</span>. <span class=\"greek\">τὰ</span> <span class=\"greek\">καθήκοντα</span> <span class=\"greek\">ἔργα</span>). <span class=\"greek\">τὰ</span> <span class=\"greek\">ἀνήκοντα</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">βουλήσει</span>, <i>o que é pertinente à vontade</i>, 1 Cl 35:5 (PTebt 294, 11: <span class=\"greek\">τὰ</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">προφητείᾳ</span> <span class=\"greek\">προσήκοντα</span> <span class=\"greek\">ἐπιτελεῖν</span>). <span class=\"greek\">τὰ</span> <span class=\"greek\">διατασσόμενα</span>, <i>executar ordens ou instruções</i> (PGM 4, 1539s.: <span class=\"greek\">τ</span>. <span class=\"greek\">ἐντολάς</span>), 1 Cl 37:2s.; cf. 40:1s.</p>\n<p class=\"entry-text\"><span class=\"greek\">τ</span>. <span class=\"greek\">λειτουργίαν</span>, <i>prestar um serviço</i> (Fílon, Somn. 1, 214; ver abaixo sobre esse termo técnico, frequentemente utilizado para reconhecer pessoas dedicadas ao bem cívico, e bibliografia sob <span class=\"greek\">λειτουργέω</span> 2), 1 Cl 20:10; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.32\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 13:32</a>, variante de leitura. <span class=\"greek\">τὰς</span> <span class=\"greek\">θεραπείας</span>, <i>as curas</i>, GJs 20:2 (não pap.). <span class=\"greek\">τὰ</span> <span class=\"greek\">κυνήγια</span>, <i>o combate com animais</i>, AcPl Ha 3, 4. <span class=\"greek\">ἁγιωσύνην</span>, <i>efetuar a santificação</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.7.1\" target=\"_blank\" rel=\"noopener noreferrer\">2 Co 7:1</a> (cf. EpArist 133: <span class=\"greek\">κακίαν</span>; 166: <span class=\"greek\">ἀκαθαρσίαν</span>). <span class=\"greek\">τὴν</span> <span class=\"greek\">σκηνήν</span>, <i>erigir a tenda</i>, isto é, executar as especificações para a construção de uma tenda, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.8.5\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 8:5</a> (ver Êx 26).</p>\n<p class=\"entry-text\">Especialmente quanto à <b>execução de ritos e cerimônias</b> (Heródoto e outros; SIG 1109, 111: <span class=\"greek\">ἐ</span>. <span class=\"greek\">τὰς</span> <span class=\"greek\">λιτουργίας</span>; UPZ 43, 20 [162/161 a.C.]; 106, 21 [99 a.C.]; PTebt 292, 20s.; Mitt-Wilck. I/2, 70, 9–11; EpArist 186; Fílon, Ebr. 129; Jos., C. Ap. 2, 118): <span class=\"greek\">τ</span>. <span class=\"greek\">λατρείας</span> <span class=\"greek\">ἐ</span>., <i>realizar os ritos</i> (Fílon, Somn. 1, 214), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.6\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:6</a>. <span class=\"greek\">θυσίας</span>, <i>oferecer sacrifícios</i> (Heródoto 2, 63; 4, 26; Diod. S. 17, 115, 6; Herodiano 1, 5, 2; índice de SIG; IPriene 108, 27; JosAs 2:5; Fílon, Somn. 1, 215; Jos., Ant. 4, 123; 9, 273; POxy 2782, 6–8 [séculos II/III d.C.]), Dg 3:5. Nesse sentido, na voz passiva (IMagnMai 17, 25s.), 1 Cl 40:3.</p>\n<p class=\"entry-text\"><span class=\"greek\">τὴν</span> <span class=\"greek\">ἡμέραν</span> <span class=\"greek\">γενέθλιον</span> <span class=\"greek\">ἐ</span>., <i>celebrar o aniversário</i>, MPol 18:2 (Epici, p. 39, 19s. B. = p. 18, 3 K.: <span class=\"greek\">γάμους</span> <span class=\"greek\">ἐπετέλεσεν</span>; Amônio, Vi. Aristot., p. 11, 23 Westerm.: <span class=\"greek\">ἑορτὴν</span> <span class=\"greek\">ἐ</span>.). Voz média, equivalente à ativa (como Políbio 1, 40, 16; 2, 58, 10; Diod. S. 3, 57, 4: <span class=\"greek\">πρᾶξιν</span> <span class=\"greek\">ἐπιτελέσασθαι</span>): <span class=\"greek\">γυναῖκες</span> <span class=\"greek\">ἐπετελέσαντο</span> <span class=\"greek\">ἀνδρεῖα</span>, <i>mulheres realizaram feitos heroicos</i>, 1 Cl 55:3.</p>\n<p class=\"entry-text\"><b>③ Fazer com que alguma coisa aconteça como cumprimento de um objetivo ou propósito: cumprir.</b> (PsSol 6:6: <span class=\"greek\">πᾶν</span> <span class=\"greek\">αἴτημα</span>; Luciano, Charon 6: <span class=\"greek\">τ</span>. <span class=\"greek\">ὑπόσχεσιν</span>.) Sobre um dito da Escritura, em passivo, 1 Cl 3:1. Aparentemente com referência ao propósito divino, <b>impor alguma coisa a alguém, realizar alguma coisa no caso de alguém</b>, com <span class=\"greek\">τινί</span> <span class=\"greek\">τι</span> (Platão, Leg. 10, 910d: <span class=\"greek\">δίκην</span> <span class=\"greek\">τινί</span>). Em passivo: <span class=\"greek\">τὰ</span> <span class=\"greek\">αὐτὰ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">παθημάτων</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ἀδελφότητι</span> <span class=\"greek\">ἐπιτελεῖσθαι</span>, <i>os mesmos tipos de sofrimento são impostos à comunidade fraterna ou se cumprem nela</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.5.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pe 5:9</a>. — DELG, s.v. <span class=\"greek\">τέλο</span>; M-M; TW.</p></section></article>\n<article id=\"entry-epitedeios-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιτήδειος, εία, ον</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epitḗdeios⟧</span><span class=\"separator\">·</span><span>adjetivo; substantivado</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Adjetivo (Homero: <span class=\"greek\">ἐπιτηδές</span>, «apropriado à situação»; ver também o verbete seguinte; Eurípides, Heródoto e outros; Ath., R. 52, 12 e outros; em geral, «necessário, adequado»). <b>Que serve a um fim ou propósito: apropriado, adequado, necessário.</b> <span class=\"greek\">καιρῷ</span> <span class=\"greek\">ἐπιτηδείῳ</span>, <i>no momento oportuno</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.25\" target=\"_blank\" rel=\"noopener noreferrer\">At 24:25</a>, variante de leitura (<span class=\"greek\">καιρὸς</span> <span class=\"greek\">ἐ</span>., como Jos., Vi. 125; 176).</p>\n<p class=\"entry-text\">Substantivado: <span class=\"greek\">τὰ</span> <span class=\"greek\">ἐ</span>., <b>o que é necessário</b> (Heródoto 2, 174, 1; Tucídides 2, 23, 3; inscrições, papiros, LXX; TestSol 3:1 D; Jos., Bell. 3, 183; Ant. 2, 326; 12, 376). Acrescentando-se <span class=\"greek\">τοῦ</span> <span class=\"greek\">σώματος</span>, <i>o que é necessário ao corpo</i>, isto é, à vida, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.16\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 2:16</a>. — B. 644; DELG, s.v. <span class=\"greek\">ἐπιτηδέ</span>; M-M; Sv.</p></section></article>\n<article id=\"entry-epitedeuma-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιτήδευμα, ατος, τό</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epitḗdeuma⟧</span><span class=\"separator\">·</span><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Ver o verbete precedente; Tucídides e outros; Diod. S. 3, 70, 7; Epicteto 3, 23, 5 e outros; Vett. Val. 73, 20; SIG 703, 15; 721, 12, 42; 766, 5; papiros, LXX; Fílon, Op. M. 80; Jos., Ant. 15, 368; C. Ap. 2, 123, 181, em sentidos diversos; Ar. 8, 6; Just., D. 3, 3; Taciano.) <b>Aquilo que alguém faz com propósito ou hábito constante: ocupação, prática, modo de viver.</b> (Hipócrates, Epid. 1, 23; Menandro, Kith., fragmento 4, 2 J.: <span class=\"greek\">ἐ</span>. <span class=\"greek\">τῷ</span> <span class=\"greek\">βίῳ</span>; Enômao, em Eus., PE 5, 34, 10: <span class=\"greek\">θεῖόν</span> <span class=\"greek\">τι</span> <span class=\"greek\">ἐ</span>. = <i>uma espécie de modo de vida divino</i>.) Da piedade cristã, Dg 1 (ver E. Blakeney, <i>The Epistle to Diognetus</i> [1943], p. 33). — DELG, s.v. <span class=\"greek\">ἐπιτηδέ</span>; TW.</p></section></article>\n<article id=\"entry-epitedeuo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιτηδεύω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epitēdeúō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Futuro, segunda pessoa singular, <span class=\"greek\">ἐπιτηδεύσεις</span>, Jr 2:33; primeiro aoristo <span class=\"greek\">ἐπετήδευσα</span> (ver o verbete precedente; Sófocles, Heródoto e outros; Diod. S. 1, 70, 2; Epicteto 3, 1, 15; 3, 5, 8; BGU 1253, 11 [século II a.C.]; LXX; En 9:6; Jos., Ant. 18, 66; C. Ap. 2, 189; Taciano; Ath., R. 48, 18 e outros). <b>Fazer de alguma coisa o objeto de seu propósito: cultivar, praticar, cuidar de.</b> Seguido de <span class=\"greek\">ὡς</span>, MPol 17:1. — DELG, s.v. <span class=\"greek\">ἐπιτηδέ</span>.</p></section></article>"};
